const row = $input.first().json;
const topic = String(row.topic ?? '').trim();
const languageCode = String(row.language_code ?? '').trim();
const researchRunId = String(row.research_run_id ?? '').trim();

if (!researchRunId || !topic || !['en','pl','ru','uk'].includes(languageCode)) {
  throw new Error('begin_research returned invalid context');
}

const stopwords = {
  en: new Set(['how','does','do','did','is','are','a','an','the','work','works','working','what','why','with','using']),
  pl: new Set(['jak','dziala','działa','dzialaja','działają','jest','sa','są','co','dlaczego','z','za','pomoca','pomocą']),
  ru: new Set(['как','работает','работают','устроен','устроена','устроено','что','почему','с','помощью']),
  uk: new Set(['як','працює','працюють','влаштований','влаштована','влаштовано','що','чому','з','за','допомогою']),
}[languageCode];

const topicTokens = topic
  .toLowerCase()
  .normalize('NFKC')
  .split(/[^\p{L}\p{N}]+/u)
  .filter(Boolean);
const subjectTokens = topicTokens.filter((token) => !stopwords.has(token));
const subject = (subjectTokens.length ? subjectTokens : topicTokens).join(' ').trim();
if (!subject) throw new Error('research subject is empty');

const principleSuffix = {
  en: 'working principle explanation',
  pl: 'zasada działania wyjaśnienie',
  ru: 'принцип работы объяснение',
  uk: 'принцип роботи пояснення',
}[languageCode];

const querySpecs = [
  {
    query_kind: 'primary_local',
    search_query: topic,
    search_language: languageCode,
    search_engine: 'duckduckgo',
    retry_1_engine: 'google',
    retry_2_engine: 'bing',
  },
  {
    query_kind: 'subject_principle',
    search_query: subject + ' ' + principleSuffix,
    search_language: languageCode,
    search_engine: 'bing',
    retry_1_engine: 'duckduckgo',
    retry_2_engine: 'google',
  },
  {
    query_kind: 'encyclopedia',
    search_query: subject,
    search_language: languageCode,
    search_engine: 'wikipedia',
    retry_1_engine: 'google',
    retry_2_engine: 'duckduckgo',
  },
];

return querySpecs.map((q, index) => ({
  json: {
    research_run_id: researchRunId,
    topic,
    language_code: languageCode,
    subject,
    subject_tokens: subjectTokens.length ? subjectTokens : topicTokens,
    query_index: index + 1,
    ...q,
  },
}));

const responses = $input.all().map((item) => item.json);
const queryInputs = $('Build Search Queries').all().map((item) => item.json);

const denyDomains = new Set([
  'facebook.com','instagram.com','tiktok.com','x.com','twitter.com',
  'pinterest.com','reddit.com','youtube.com','youtu.be'
]);

function canonicalize(result) {
  const raw = String(result?.url ?? '').trim();
  const parsed = Array.isArray(result?.parsed_url) ? result.parsed_url : [];

  let scheme = String(parsed[0] ?? '').trim().toLowerCase();
  let authority = String(parsed[1] ?? '').trim();
  let path = String(parsed[2] ?? '').trim();
  let query = String(parsed[4] ?? '').trim();

  if (!scheme || !authority) {
    const match = raw.match(/^(https?):\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?/i);
    if (!match) return null;
    scheme = String(match[1] ?? '').toLowerCase();
    authority = String(match[2] ?? '');
    path = String(match[3] ?? '');
    query = String(match[4] ?? '');
  }

  if (!['http','https'].includes(scheme)) return null;

  const authorityNoUser = authority.split('@').pop() ?? '';
  const host = authorityNoUser
    .replace(/:\d+$/, '')
    .replace(/^www\./i, '')
    .toLowerCase();

  if (!host || host === 'localhost' || host.endsWith('.local')) return null;
  if (/^(127\.|10\.|192\.168\.|169\.254\.)/.test(host)) return null;
  const private172 = host.match(/^172\.(\d+)\./);
  if (
    private172 &&
    Number(private172[1]) >= 16 &&
    Number(private172[1]) <= 31
  ) return null;
  if (host === '::1' || host === '0.0.0.0') return null;

  if ([...denyDomains].some((d) => host === d || host.endsWith('.' + d))) {
    return null;
  }

  if (/\.(pdf|jpe?g|png|gif|webp|svg|mp4|mov|avi|zip|gz)$/i.test(path)) {
    return null;
  }

  path = path || '/';
  if (path !== '/') path = path.replace(/\/+$/, '');

  const cleanQueryParts = query
    ? query
        .split('&')
        .filter(Boolean)
        .filter((part) => {
          const rawKey = part.split('=', 1)[0] ?? '';
          let key = rawKey;
          try { key = decodeURIComponent(rawKey); } catch {}
          key = key.toLowerCase();
          return !(
            key.startsWith('utm_') ||
            ['fbclid','gclid','dclid','msclkid'].includes(key)
          );
        })
        .sort()
    : [];

  const normalizedAuthority = authority.toLowerCase();
  const canonical =
    scheme + '://' + normalizedAuthority + path +
    (cleanQueryParts.length ? '?' + cleanQueryParts.join('&') : '');

  return {
    canonical_url: canonical,
    source_domain: host,
  };
}

function cleanSnippet(value) {
  return String(value ?? '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 2000);
}

function lexicalTokens(value) {
  return String(value ?? '')
    .toLowerCase()
    .normalize('NFKC')
    .split(/[^\p{L}\p{N}]+/u)
    .filter(Boolean);
}

function sameLexemeFamily(left,right) {
  if (left === right) return true;
  const min = Math.min(left.length,right.length);
  if (min < 5) return false;
  return left.slice(0,5) === right.slice(0,5);
}

function isTopicRelevant(result, query) {
  const subjectTokens = Array.isArray(query.subject_tokens)
    ? query.subject_tokens.map((x) => String(x ?? '').toLowerCase()).filter(Boolean)
    : [];
  if (!subjectTokens.length) return true;
  const haystack = lexicalTokens(
    String(result?.title ?? '') + ' ' +
    String(result?.content ?? result?.snippet ?? '') + ' ' +
    String(result?.url ?? '')
  );
  return subjectTokens.some((subjectToken) =>
    haystack.some((candidateToken) => sameLexemeFamily(subjectToken,candidateToken))
  );
}

const raw = [];
for (let responseIndex = 0; responseIndex < responses.length; responseIndex += 1) {
  const response = responses[responseIndex] ?? {};
  const q = queryInputs[responseIndex] ?? {};
  const results = Array.isArray(response.results) ? response.results : [];

  for (let resultIndex = 0; resultIndex < Math.min(results.length, 12); resultIndex += 1) {
    const result = results[resultIndex] ?? {};
    const normalized = canonicalize(result);
    if (!normalized) continue;
    if (!isTopicRelevant(result, q)) continue;

    raw.push({
      research_run_id: q.research_run_id,
      topic: q.topic,
      language_code: q.language_code,
      subject: q.subject,
      subject_tokens: q.subject_tokens,
      search_query: q.search_query,
      query_kind: q.query_kind,
      query_index: Number(q.query_index ?? responseIndex + 1),
      search_rank: resultIndex + 1,
      search_engines: Array.isArray(result.engines) ? result.engines : [],
      source_url: String(result.url ?? '').trim(),
      canonical_url: normalized.canonical_url,
      source_domain: normalized.source_domain,
      title: String(result.title ?? normalized.source_domain).trim().slice(0, 1000),
      snippet: cleanSnippet(result.content ?? result.snippet),
    });
  }
}

const seenUrl = new Set();
const selected = [];
const domainCount = new Map();

function add(candidate, maxPerDomain) {
  if (!candidate || selected.length >= 10) return;
  if (seenUrl.has(candidate.canonical_url)) return;
  const used = domainCount.get(candidate.source_domain) ?? 0;
  if (used >= maxPerDomain) return;
  seenUrl.add(candidate.canonical_url);
  domainCount.set(candidate.source_domain, used + 1);
  selected.push(candidate);
}

raw.forEach((candidate) => add(candidate, 1));
if (selected.length < 10) {
  raw.forEach((candidate) => add(candidate, 2));
}

if (selected.length === 0) {
  const ctx = queryInputs[0] ?? {};
  return [{
    json: {
      research_run_id: ctx.research_run_id,
      candidate_valid: false,
      reason: 'no_fetch_candidates',
    },
  }];
}

return selected.map((candidate) => ({
  json: {
    ...candidate,
    candidate_valid: true,
  },
}));

const candidate = $('Build Fetch Candidates').item.json;
const fetch = $('Fetch Source Page').item.json;
const extracted = $json ?? {};

const statusCode = Number(fetch.statusCode ?? fetch.status ?? 0);
const headers = fetch.headers && typeof fetch.headers === 'object' ? fetch.headers : {};
const contentTypeRaw =
  headers['content-type'] ??
  headers['Content-Type'] ??
  '';
const contentType = Array.isArray(contentTypeRaw)
  ? String(contentTypeRaw[0] ?? '')
  : String(contentTypeRaw ?? '');

const isHtml =
  contentType.toLowerCase().includes('text/html') ||
  contentType === '';

let text = typeof extracted.body_text === 'string'
  ? extracted.body_text
  : '';
text = text.replace(/\s+/g, ' ').trim();

if (!isHtml || statusCode < 200 || statusCode > 299) {
  text = '';
}

const MAX_SOURCE_CHARS = 12000;
if (text.length > MAX_SOURCE_CHARS) {
  text = text.slice(0, MAX_SOURCE_CHARS);
}

const extractedTitle =
  typeof extracted.page_title === 'string'
    ? extracted.page_title.replace(/\s+/g, ' ').trim()
    : '';

return {
  json: {
    research_run_id: candidate.research_run_id,
    search_query: candidate.search_query,
    search_rank: candidate.search_rank,
    search_engines: candidate.search_engines,
    source_url: candidate.source_url,
    canonical_url: candidate.canonical_url,
    source_domain: candidate.source_domain,
    title: (extractedTitle || candidate.title || candidate.source_domain).slice(0, 1000),
    snippet: String(candidate.snippet ?? '').slice(0, 2000),
    content_text: text,
    source_http_status: statusCode,
    source_content_type: contentType || 'unknown',
    extracted_chars: text.length,
  },
};

const ctx = $('Begin Research').first().json;
const runId = String(ctx.research_run_id ?? '').trim();
if (!runId) throw new Error('research_run_id missing after evidence storage');
const rows = $input.all().map((item) => item.json);
return [{
  json: {
    research_run_id: runId,
    store_attempts: rows.length,
    inserted_count: rows.filter((r) => r.inserted === true).length,
  },
}];

if ($json.research_status !== 'passed') {
  throw new Error(
    'M4 research failed closed: evidence=' +
    String($json.evidence_count ?? 0) +
    ', domains=' +
    String($json.independent_domain_count ?? 0)
  );
}
return {
  json: {
    research_status: $json.research_status,
    evidence_count: Number($json.evidence_count),
    independent_domain_count: Number($json.independent_domain_count),
  },
};

const ctx = $('Begin Research').first().json;
const runId = String(ctx.research_run_id ?? '').trim();
if (!runId) throw new Error('cannot record research failure: research_run_id missing');

const errorObject =
  $json.error && typeof $json.error === 'object' && !Array.isArray($json.error)
    ? $json.error
    : {};

const candidates = [
  errorObject.message,
  $json.message,
  $json.description,
  typeof $json.error === 'string' ? $json.error : null,
];

const message = candidates.find(
  (value) => typeof value === 'string' && value.trim().length > 0
) ?? 'unspecified M4 workflow failure';

return {
  json: {
    research_run_id: runId,
    error_message: ('M4 research workflow failed: ' + message.trim()).slice(0, 4000),
  },
};

const queries = $('Build Search Queries').all().map((item) => item.json);
if (!queries.length) throw new Error('M4 retry 1 query context missing');
return queries.map((query) => ({
  json: {
    ...query,
    search_engine: String(query.retry_1_engine ?? query.search_engine ?? 'yahoo'),
  },
}));

