const domainCount = new Map();

function add(candidate, maxPerDomain) {
  if (!candidate || selected.length >= 10) return;
  if (seenUrl.has(candidate.canonical_url)) return;
  const used = domainCount.get(candidate.source_domain) ?? 0;
  if (used >= maxPerDomain) return;
  seenUrl.add(candidate.canonical_url);
  domainCount.set(candidate.source_domain, used + 1);
  selected.push(candidate);
}

raw.forEach((candidate) => add(candidate, 1));
if (selected.length < 10) {
  raw.forEach((candidate) => add(candidate, 2));
}

if (selected.length === 0) {
  const ctx = queryInputs[0] ?? {};
  return [{
    json: {
      research_run_id: ctx.research_run_id,
      candidate_valid: false,
      reason: 'no_fetch_candidates',
    },
  }];
}

return selected.map((candidate) => ({
  json: {
    ...candidate,
    candidate_valid: true,
  },
}));
